     1→import { useState, useCallback } from "react";
     2→import type {
     3→  ActionFunctionArgs,
     4→  HeadersFunction,
     5→  LoaderFunctionArgs,
     6→} from "react-router";
     7→import { useFetcher, useLoaderData, useNavigate } from "react-router";
     8→import { useAppBridge } from "@shopify/app-bridge-react";
     9→import { authenticate } from "../shopify.server";
    10→import { boundary } from "@shopify/shopify-app-react-router/server";
    11→import db from "../db.server";
    12→import {
    13→  Page,
    14→  Layout,
    15→  Card,
    16→  BlockStack,
    17→  InlineStack,
    18→  InlineGrid,
    19→  Text,
    20→  Button,
    21→  TextField,
    22→  Select,
    23→  Checkbox,
    24→  Divider,
    25→  Box,
    26→  Banner,
    27→} from "@shopify/polaris";
    28→
    29→export const loader = async ({ request }: LoaderFunctionArgs) => {
    30→  const { session } = await authenticate.admin(request);
    31→  const shop = session.shop;
    32→
    33→  let config = await db.widgetConfig.findUnique({ where: { shop } });
    34→
    35→  if (!config) {
    36→    config = await db.widgetConfig.create({ data: { shop } });
    37→  }
    38→
    39→  const themeEditorUrl = `https://${shop}/admin/themes/current/editor`;
    40→
    41→  return { config, themeEditorUrl };
    42→};
    43→
    44→export const action = async ({ request }: ActionFunctionArgs) => {
    45→  const { session } = await authenticate.admin(request);
    46→  const shop = session.shop;
    47→  const formData = await request.formData();
    48→  const intent = formData.get("intent");
    49→
    50→  if (intent === "save") {
    51→    const data = {
    52→      position: String(formData.get("position") || "inline"),
    53→      primaryColor: String(formData.get("primaryColor") || "#008060"),
    54→      successColor: String(formData.get("successColor") || "#008060"),
    55→      errorColor: String(formData.get("errorColor") || "#D72C0D"),
    56→      backgroundColor: String(formData.get("backgroundColor") || "#FFFFFF"),
    57→      textColor: String(formData.get("textColor") || "#202223"),
    58→      heading: String(formData.get("heading") || "Check Delivery Availability"),
    59→      placeholder: String(formData.get("placeholder") || "Enter your zip code"),
    60→      buttonText: String(formData.get("buttonText") || "Check"),
    61→      successMessage: String(
    62→        formData.get("successMessage") ||
    63→          "Great news! We deliver to your area.",
    64→      ),
    65→      errorMessage: String(
    66→        formData.get("errorMessage") ||
    67→          "Sorry, we don't deliver to this area yet.",
    68→      ),
    69→      notFoundMessage: String(
    70→        formData.get("notFoundMessage") ||
    71→          "This zip code was not found in our system.",
    72→      ),
    73→      showEta: formData.get("showEta") === "true",
    74→      showZone: formData.get("showZone") === "true",
    75→      showWaitlistOnFailure: formData.get("showWaitlistOnFailure") === "true",
    76→      borderRadius: String(formData.get("borderRadius") || "8"),
    77→      customCss: String(formData.get("customCss") || "") || null,
    78→    };
    79→
    80→    await db.widgetConfig.upsert({
    81→      where: { shop },
    82→      create: { shop, ...data },
    83→      update: data,
    84→    });
    85→
    86→    return { success: true };
    87→  }
    88→
    89→  if (intent === "reset") {
    90→    await db.widgetConfig.upsert({
    91→      where: { shop },
    92→      create: { shop },
    93→      update: {
    94→        position: "inline",
    95→        primaryColor: "#008060",
    96→        successColor: "#008060",
    97→        errorColor: "#D72C0D",
    98→        backgroundColor: "#FFFFFF",
    99→        textColor: "#202223",
   100→        heading: "Check Delivery Availability",
   101→        placeholder: "Enter your zip code",
   102→        buttonText: "Check",
   103→        successMessage: "Great news! We deliver to your area.",
   104→        errorMessage: "Sorry, we don't deliver to this area yet.",
   105→        notFoundMessage: "This zip code was not found in our system.",
   106→        showEta: true,
   107→        showZone: false,
   108→        showWaitlistOnFailure: false,
   109→        borderRadius: "8",
   110→        customCss: null,
   111→      },
   112→    });
   113→    return { success: true, action: "reset" };
   114→  }
   115→
   116→  return null;
   117→};
   118→
   119→type WidgetConfig = {
   120→  position: string;
   121→  primaryColor: string;
   122→  successColor: string;
   123→  errorColor: string;
   124→  backgroundColor: string;
   125→  textColor: string;
   126→  heading: string;
   127→  placeholder: string;
   128→  buttonText: string;
   129→  successMessage: string;
   130→  errorMessage: string;
   131→  notFoundMessage: string;
   132→  showEta: boolean;
   133→  showZone: boolean;
   134→  showWaitlistOnFailure: boolean;
   135→  borderRadius: string;
   136→  customCss: string | null;
   137→};
   138→
   139→export default function WidgetPage() {
   140→  const { config, themeEditorUrl } = useLoaderData<typeof loader>();
   141→  const fetcher = useFetcher<typeof action>();
   142→  const shopify = useAppBridge();
   143→  const navigate = useNavigate();
   144→
   145→  const c = config as WidgetConfig;
   146→
   147→  // Form state initialized from DB
   148→  const [position, setPosition] = useState(c.position);
   149→  const [primaryColor, setPrimaryColor] = useState(c.primaryColor);
   150→  const [successColor, setSuccessColor] = useState(c.successColor);
   151→  const [errorColor, setErrorColor] = useState(c.errorColor);
   152→  const [backgroundColor, setBackgroundColor] = useState(c.backgroundColor);
   153→  const [textColor, setTextColor] = useState(c.textColor);
   154→  const [heading, setHeading] = useState(c.heading);
   155→  const [placeholder, setPlaceholder] = useState(c.placeholder);
   156→  const [buttonText, setButtonText] = useState(c.buttonText);
   157→  const [successMessage, setSuccessMessage] = useState(c.successMessage);
   158→  const [errorMessage, setErrorMessage] = useState(c.errorMessage);
   159→  const [notFoundMessage, setNotFoundMessage] = useState(c.notFoundMessage);
   160→  const [showEta, setShowEta] = useState(c.showEta);
   161→  const [showZone, setShowZone] = useState(c.showZone);
   162→  const [showWaitlistOnFailure, setShowWaitlistOnFailure] = useState(
   163→    c.showWaitlistOnFailure,
   164→  );
   165→  const [borderRadius, setBorderRadius] = useState(c.borderRadius);
   166→  const [customCss, setCustomCss] = useState(c.customCss || "");
   167→
   168→  // Preview state
   169→  const [previewState, setPreviewState] = useState<
   170→    "idle" | "success" | "error" | "notfound"
   171→  >("idle");
   172→
   173→  const isSaving =
   174→    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "save";
   175→  const saved =
   176→    fetcher.data &&
   177→    "success" in fetcher.data &&
   178→    fetcher.data.success &&
   179→    !("action" in fetcher.data);
   180→
   181→  const handleSave = useCallback(() => {
   182→    const fd = new FormData();
   183→    fd.set("intent", "save");
   184→    fd.set("position", position);
   185→    fd.set("primaryColor", primaryColor);
   186→    fd.set("successColor", successColor);
   187→    fd.set("errorColor", errorColor);
   188→    fd.set("backgroundColor", backgroundColor);
   189→    fd.set("textColor", textColor);
   190→    fd.set("heading", heading);
   191→    fd.set("placeholder", placeholder);
   192→    fd.set("buttonText", buttonText);
   193→    fd.set("successMessage", successMessage);
   194→    fd.set("errorMessage", errorMessage);
   195→    fd.set("notFoundMessage", notFoundMessage);
   196→    fd.set("showEta", String(showEta));
   197→    fd.set("showZone", String(showZone));
   198→    fd.set("showWaitlistOnFailure", String(showWaitlistOnFailure));
   199→    fd.set("borderRadius", borderRadius);
   200→    fd.set("customCss", customCss);
   201→    fetcher.submit(fd, { method: "POST" });
   202→    shopify.toast.show("Widget settings saved");
   203→  }, [
   204→    position,
   205→    primaryColor,
   206→    successColor,
   207→    errorColor,
   208→    backgroundColor,
   209→    textColor,
   210→    heading,
   211→    placeholder,
   212→    buttonText,
   213→    successMessage,
   214→    errorMessage,
   215→    notFoundMessage,
   216→    showEta,
   217→    showZone,
   218→    showWaitlistOnFailure,
   219→    borderRadius,
   220→    customCss,
   221→    fetcher,
   222→    shopify,
   223→  ]);
   224→
   225→  const handleReset = useCallback(() => {
   226→    const fd = new FormData();
   227→    fd.set("intent", "reset");
   228→    fetcher.submit(fd, { method: "POST" });
   229→    setPosition("inline");
   230→    setPrimaryColor("#008060");
   231→    setSuccessColor("#008060");
   232→    setErrorColor("#D72C0D");
   233→    setBackgroundColor("#FFFFFF");
   234→    setTextColor("#202223");
   235→    setHeading("Check Delivery Availability");
   236→    setPlaceholder("Enter your zip code");
   237→    setButtonText("Check");
   238→    setSuccessMessage("Great news! We deliver to your area.");
   239→    setErrorMessage("Sorry, we don't deliver to this area yet.");
   240→    setNotFoundMessage("This zip code was not found in our system.");
   241→    setShowEta(true);
   242→    setShowZone(false);
   243→    setShowWaitlistOnFailure(false);
   244→    setBorderRadius("8");
   245→    setCustomCss("");
   246→    setPreviewState("idle");
   247→    shopify.toast.show("Widget settings reset to defaults");
   248→  }, [fetcher, shopify]);
   249→
   250→  const positionOptions = [
   251→    { label: "Inline (embedded in page)", value: "inline" },
   252→    { label: "Floating button", value: "floating" },
   253→    { label: "Popup modal", value: "popup" },
   254→  ];
   255→
   256→  // Live preview widget
   257→  const WidgetPreview = () => {
   258→    const rad = `${borderRadius}px`;
   259→
   260→    const resultMessage =
   261→      previewState === "success"
   262→        ? successMessage
   263→        : previewState === "error"
   264→          ? errorMessage
   265→          : previewState === "notfound"
   266→            ? notFoundMessage
   267→            : null;
   268→
   269→    const resultColor =
   270→      previewState === "success"
   271→        ? successColor
   272→        : previewState === "error" || previewState === "notfound"
   273→          ? errorColor
   274→          : "transparent";
   275→
   276→    return (
   277→      <div
   278→        style={{
   279→          backgroundColor,
   280→          color: textColor,
   281→          borderRadius: rad,
   282→          padding: "24px",
   283→          border: "1px solid #e1e3e5",
   284→          fontFamily:
   285→            '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
   286→          maxWidth: "400px",
   287→        }}
   288→      >
   289→        <div
   290→          style={{
   291→            fontSize: "16px",
   292→            fontWeight: 600,
   293→            marginBottom: "16px",
   294→            color: textColor,
   295→          }}
   296→        >
   297→          {heading}
   298→        </div>
   299→        <div style={{ display: "flex", gap: "8px", marginBottom: "12px" }}>
   300→          <input
   301→            type="text"
   302→            placeholder={placeholder}
   303→            readOnly
   304→            style={{
   305→              flex: 1,
   306→              padding: "10px 12px",
   307→              border: "1px solid #c9cccf",
   308→              borderRadius: rad,
   309→              fontSize: "14px",
   310→              outline: "none",
   311→              color: textColor,
