     1→/**
     2→ * Public API endpoint for the storefront zip code widget.
     3→ *
     4→ * Called from the merchant's storefront (Theme App Extension or custom JS)
     5→ * to check whether a zip code is serviceable.
     6→ *
     7→ * GET/POST /api/zip-check?shop=store.myshopify.com&zip=12345
     8→ *
     9→ * Response:
    10→ *   200 { allowed: true,  message: "...", eta: "...", zone: "..." }
    11→ *   200 { allowed: false, message: "..." }
    12→ *   400 { error: "Missing shop or zip parameter" }
    13→ *   404 { allowed: false, message: "Zip code not found", notFound: true }
    14→ */
    15→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
    16→import db from "../db.server";
    17→
    18→const CORS_HEADERS = {
    19→  "Access-Control-Allow-Origin": "*",
    20→  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    21→  "Access-Control-Allow-Headers": "Content-Type",
    22→  "Content-Type": "application/json",
    23→};
    24→
    25→async function handleZipCheck(shop: string | null, zip: string | null) {
    26→  if (!shop || !zip) {
    27→    return new Response(
    28→      JSON.stringify({ error: "Missing shop or zip parameter" }),
    29→      { status: 400, headers: CORS_HEADERS },
    30→    );
    31→  }
    32→
    33→  const normalizedZip = zip.trim().toUpperCase();
    34→
    35→  const zipRecord = await db.zipCode.findUnique({
    36→    where: { shop_zipCode: { shop, zipCode: normalizedZip } },
    37→  });
    38→
    39→  // Fetch widget config for custom messages (falls back to defaults)
    40→  const widgetConfig = await db.widgetConfig.findUnique({ where: { shop } });
    41→
    42→  if (!zipRecord || !zipRecord.isActive) {
    43→    // Check if zip exists but is inactive — treat as not found
    44→    const successMsg =
    45→      widgetConfig?.successMessage ?? "Great news! We deliver to your area.";
    46→    const notFoundMsg =
    47→      widgetConfig?.notFoundMessage ??
    48→      "This zip code was not found in our system.";
    49→
    50→    if (!zipRecord) {
    51→      return new Response(
    52→        JSON.stringify({
    53→          allowed: false,
    54→          message: notFoundMsg,
    55→          notFound: true,
    56→        }),
    57→        { status: 200, headers: CORS_HEADERS },
    58→      );
    59→    }
    60→
    61→    // Inactive zip — treat same as not found
    62→    return new Response(
    63→      JSON.stringify({ allowed: false, message: notFoundMsg, notFound: true }),
    64→      { status: 200, headers: CORS_HEADERS },
    65→    );
    66→  }
    67→
    68→  if (zipRecord.type === "blocked") {
    69→    const errorMsg =
    70→      zipRecord.message ??
    71→      widgetConfig?.errorMessage ??
    72→      "Sorry, we don't deliver to this area yet.";
    73→
    74→    return new Response(
    75→      JSON.stringify({ allowed: false, message: errorMsg }),
    76→      { status: 200, headers: CORS_HEADERS },
    77→    );
    78→  }
    79→
    80→  // Allowed
    81→  const successMsg =
    82→    zipRecord.message ??
    83→    widgetConfig?.successMessage ??
    84→    "Great news! We deliver to your area.";
    85→
    86→  return new Response(
    87→    JSON.stringify({
    88→      allowed: true,
    89→      message: successMsg,
    90→      eta: widgetConfig?.showEta ? (zipRecord.eta ?? null) : null,
    91→      zone: widgetConfig?.showZone ? (zipRecord.zone ?? null) : null,
    92→      showWaitlist: false,
    93→    }),
    94→    { status: 200, headers: CORS_HEADERS },
    95→  );
    96→}
    97→
    98→// Handle GET requests: ?shop=...&zip=...
    99→export const loader = async ({ request }: LoaderFunctionArgs) => {
   100→  const url = new URL(request.url);
   101→
   102→  // Handle CORS preflight
   103→  if (request.method === "OPTIONS") {
   104→    return new Response(null, { status: 204, headers: CORS_HEADERS });
   105→  }
   106→
   107→  const shop = url.searchParams.get("shop");
   108→  const zip = url.searchParams.get("zip");
   109→  return handleZipCheck(shop, zip);
   110→};
   111→
   112→// Handle POST requests with JSON body: { shop, zip }
   113→export const action = async ({ request }: ActionFunctionArgs) => {
   114→  if (request.method === "OPTIONS") {
   115→    return new Response(null, { status: 204, headers: CORS_HEADERS });
   116→  }
   117→
   118→  let shop: string | null = null;
   119→  let zip: string | null = null;
   120→
   121→  try {
   122→    const body = await request.json();
   123→    shop = body?.shop ?? null;
   124→    zip = body?.zip ?? null;
   125→  } catch {
   126→    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
   127→      status: 400,
   128→      headers: CORS_HEADERS,
   129→    });
   130→  }
   131→
   132→  return handleZipCheck(shop, zip);
   133→};
